<?php
namespace ZinCelestial\Platform\Database; defined('ABSPATH')||exit;
final class AtomicLock{private string $name;private string $token='';public function __construct(string $name){$this->name='zcp_'.sanitize_key($name);}public function acquire(int $ttl=300):bool{global $wpdb;$this->token=wp_generate_uuid4();$key=$this->name;$value=wp_json_encode(array('token'=>$this->token,'expires'=>time()+max(30,$ttl)));$sql=$wpdb->prepare("INSERT INTO {$wpdb->sitemeta} (site_id,meta_key,meta_value) VALUES (%d,%s,%s) ON DUPLICATE KEY UPDATE meta_value=IF(CAST(JSON_UNQUOTE(JSON_EXTRACT(meta_value,'$.expires')) AS UNSIGNED)<%d,VALUES(meta_value),meta_value)",get_current_network_id(),$key,$value,time());$wpdb->query($sql);$stored=get_site_option($key,array());return is_array($stored)&&($stored['token']??'')===$this->token;}public function release():bool{$stored=get_site_option($this->name,array());if(($stored['token']??'')!==$this->token)return false;return delete_site_option($this->name);} }
